.router-overview-framework {
  --ro-border: #d8dde6;
  --ro-line: #e8edf3;
  --ro-page: #f3f6fa;
  --ro-surface: #ffffff;
  --ro-surface-soft: #f8fbfe;
  --ro-surface-muted: #f5f8fc;
  --ro-text: #17202b;
  --ro-muted: #667184;
  --ro-faint: #8c96a6;
  --ro-blue: #3f7fbd;
  --ro-warn: #f08c00;
  --ro-danger: #d93025;
  --ro-ok: #256c3a;
  --ro-primary: #1f5fa8;
  --ro-secondary: #5e6c82;
  color: var(--ro-text);
  background: var(--ro-page);
  font-family: "Microsoft YaHei UI", "Microsoft YaHei", "Segoe UI", sans-serif;
  font-size: 12px;
  line-height: 1.28;
  min-height: 100vh;
  padding: 8px;
  box-sizing: border-box;
}

