    max-height: none;
    overflow: visible;
  }

  .ik-mobile-detail-row.is-four-col {
    grid-template-columns: minmax(58px, .76fr) minmax(40px, .46fr) minmax(0, .96fr) minmax(0, 1fr);
    min-height: 16px;
    max-height: none;
    overflow: visible;
  }

  .ro-mobile-detail-table[data-overview-mobile-density-module="mobile-interface-forwarding"] .ik-mobile-detail-row.is-four-col {
