}

.ro-desktop-key-row {
  display: grid;
  grid-template-columns: 1.35fr repeat(5, minmax(0, 1fr));
  gap: 1px;
  margin: 0 0 6px;
  border: 1px solid var(--ro-border);
  background: var(--ro-border);
}

.ro-desktop-key-cell {
  min-width: 0;
  min-height: 48px;
  padding: 5px 7px 4px;
  background: #fff;
